class Solution { private long manhattan(int x1,int y1,int x2,int y2){return Math.abs((long)x1-x2)+Math.abs((long)y1-y2);}public int minimumCost(int[] start,int[] target,int[][] specialRoads){int roads=specialRoads.length;long[] distance=new long[roads];Arrays.fill(distance,Long.MAX_VALUE);PriorityQueue<long[]> queue=new PriorityQueue<>(Comparator.comparingLong(state->state[0]));queue.add(new long[]{0,start[0],start[1],-1});long answer=manhattan(start[0],start[1],target[0],target[1]);while(!queue.isEmpty()){long[] state=queue.poll();long cost=state[0];int x=(int)state[1],y=(int)state[2],index=(int)state[3];if(index>=0&&cost!=distance[index])continue;answer=Math.min(answer,cost+manhattan(x,y,target[0],target[1]));for(int i=0;i<roads;i++){int[] road=specialRoads[i];long next=cost+manhattan(x,y,road[0],road[1])+road[4];if(next<distance[i]){distance[i]=next;queue.add(new long[]{next,road[2],road[3],i});}}}return (int)answer;} }
